package com.mohymods.kingdomsmp.economy;
import com.mohymods.kingdomsmp.equipment.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import java.io.IOException;
import static org.junit.jupiter.api.Assertions.*;
/** Canonical transaction/fault models; no native quest/rank evidence is fabricated. */
class MasterWorkStoreTest {
 @TempDir Path directory;final UUID player=UUID.randomUUID();
 static CompoundTag item(String id){var t=new CompoundTag();t.putString("id",id);t.putInt("count",1);return t;}
 static CompoundTag work(){var data=new CompoundTag();var before=new ListTag();var after=new ListTag();for(int i=0;i<36;i++){before.add(i==0?item("minecraft:diamond_sword"):i==1?item("minecraft:enchanted_book"):new CompoundTag());after.add(i==0?item("minecraft:diamond_sword"):new CompoundTag());}data.put("before",before);data.put("after",after);data.put("world",new ListTag());data.putInt("xp",3);data.putString("dimension","minecraft:overworld");var xp=new CompoundTag();xp.putInt("before",40);xp.putInt("after",37);xp.putInt("total",2000);xp.putFloat("progress",.5f);data.put("xpState",xp);return data;}
 @Test void exactReceiptCommitsOnlyOnceAndArchivesWithoutWalletOrMailMint()throws Exception{var s=EconomyStore.open(directory);var id=UUID.randomUUID();var pending=s.prepareMasterWork(id,player,MasterGear.CODEX.id(),work());assertEquals(0,s.revision());assertTrue(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));assertEquals(1,s.revision());assertEquals(pending.sequence(),s.expectedReceipt(player));assertEquals(pending.sequence(),EconomyStore.open(directory).expectedReceipt(player));assertEquals(0,s.balance(player));assertTrue(s.itemMailbox(player).isEmpty());s.archive(player,"Master native exchange receipt model");var reopened=EconomyStore.open(directory);assertEquals(1,reopened.revision());assertThrows(IllegalArgumentException.class,()->reopened.prepareMasterWork(id,player,MasterGear.CODEX.id(),work()));}
 @Test void previousReceiptAbortsAndForeignReceiptsNeverGuess()throws Exception{var s=EconomyStore.open(directory);var pending=s.prepareMasterWork(UUID.randomUUID(),player,MasterGear.EXTRACTION.id(),work());assertThrows(IOException.class,()->s.recoverItem(new EconomyStore.Receipt(UUID.randomUUID(),pending.sequence())));assertTrue(s.pendingItem().isPresent());assertFalse(s.recoverItem(EconomyStore.Receipt.empty()));assertEquals(0,EconomyStore.open(directory).revision());}
 @Test void afterRenameUncertaintyRestoresOneCommitOrOneAbort()throws Exception{var s=EconomyStore.open(directory);var p=s.prepareMasterWork(UUID.randomUUID(),player,MasterGear.CODEX.id(),work());var failing=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("after rename");});assertThrows(IOException.class,()->failing.recoverItem(new EconomyStore.Receipt(s.id(),p.sequence())));var restored=EconomyStore.open(directory);assertEquals(1,restored.revision());assertTrue(restored.pendingItem().isEmpty());assertTrue(restored.itemMailbox(player).isEmpty());}
 @Test void malformedCostsInventoriesAndKindsRefuseBeforeAnyReceipt()throws Exception{var s=EconomyStore.open(directory);var invalid=work();invalid.getCompound("xpState").putInt("after",40);assertThrows(IllegalArgumentException.class,()->s.prepareMasterWork(UUID.randomUUID(),player,MasterGear.CODEX.id(),invalid));var wrong=work();wrong.getList("before",Tag.TAG_COMPOUND).remove(0);assertThrows(IllegalArgumentException.class,()->s.prepareMasterWork(UUID.randomUUID(),player,MasterGear.CODEX.id(),wrong));assertThrows(IllegalArgumentException.class,()->s.prepareMasterWork(UUID.randomUUID(),player,MasterGear.AXE.id(),work()));assertTrue(s.pendingItem().isEmpty());assertEquals(0,s.revision());}
 @Test void allFivePurchasesRequireTheCorrespondingActiveMasterBeforeSpending()throws Exception{for(var gear:MasterGear.values()){var s=EconomyStore.open(directory.resolve(gear.path()));s.adminSet(UUID.randomUUID(),player,player,200000,"Explicit isolated purchase-denial model funds");assertThrows(IllegalStateException.class,()->s.buyMasterGear(UUID.randomUUID(),player,gear.id(),50000,item(gear.id())));s.changeProfession(UUID.randomUUID(),player,"enroll","",gear.role().id());assertThrows(IllegalStateException.class,()->s.buyMasterGear(UUID.randomUUID(),player,gear.id(),50000,item(gear.id())));assertEquals(200000,s.balance(player));assertEquals(0,s.equipmentPurchases(player,gear.id()));assertTrue(s.itemMailbox(player).isEmpty());}}
}
